 title=part.split('\n')[0];m=re.match(r'第 (\d+) 次',title)
 anchor='lesson-'+m.group(1) if m else ('setup' if title.startswith('家长先准备') else 'reading-'+str(i))
 content=markdown.markdown(('## ' if i else '')+part,extensions=['tables','fenced_code'])
